package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.content.*;import android.location.*;import android.net.Uri;
import com.insight.quantlife.*;import org.json.*;import java.io.*;import java.util.*;
import org.mapsforge.map.reader.MapFile;import org.mapsforge.core.model.BoundingBox;

/** Synthetic data only, disposable emulator. No user location or public tile requests. */
public final class TrackOfflineUpgradeTest extends Instrumentation {
 MainHost h;int passed;String phase;final String date="2026-11-03",full="2026-11-04";
 @Override public void onCreate(Bundle b){super.onCreate(b);phase=b==null?"verify":b.getString("phase","verify");start();}
 void check(boolean ok,String label)throws Exception{if(!ok)throw new Exception(label);passed++;Bundle s=new Bundle();s.putString("stream","PASS "+label+"\n");sendStatus(0,s);}
 Location point(long t,int i){Location l=new Location("gps");l.setLatitude(0.01+i*.00001);l.setLongitude(.01);l.setAccuracy(10);l.setTime(t);l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());l.setSpeed(1.1f);l.setSpeedAccuracyMetersPerSecond(.1f);return l;}
 void until(String expr)throws Exception{for(int i=0;i<120;i++){if(h.js(expr).equals("true"))return;Thread.sleep(100);}throw new Exception("UI timeout: "+expr);}
 @Override public void onStart(){Bundle result=new Bundle();LocationManager manager=null;try(TrackStore db=new TrackStore(getTargetContext())){
  getTargetContext().stopService(new Intent(getTargetContext(),TrackingService.class));h=new MainHost(this);h.open();h.js("AutoWiki.pause()");
  if(phase.equals("visual")){
   File vector=new File(getTargetContext().getFilesDir(),"qa-vector.map");OfflineMap.importFile(getTargetContext(),Uri.fromFile(vector));h.call("trackConfig",new JSONObject().put("mapMode","offline").put("mapConsent",false));
   db.deleteDay("2026-11-05");long vb=TrackStore.dayStart("2026-11-05")+36000000;for(int i=0;i<10;i++){Location v=point(vb+i*5000,i);v.setLatitude(.02+i*.00001);v.setLongitude(.04+i*.00002);db.add(v,"vector-road-visual");}
   h.js("document.querySelector('[data-page=tracks]').click()");until("!!document.querySelector('#track-date')");h.js("document.querySelector('#track-date').value='2026-11-05';document.querySelector('#track-date').dispatchEvent(new Event('change'))");until("document.querySelector('#track-map-message').textContent.includes('离线 OSM 底图')");
   h.js("document.querySelector('.track-map-frame').scrollIntoView({block:'start'});document.querySelector('#track-zoom-in').click();document.querySelector('#track-zoom-in').click()");Thread.sleep(1500);h.tap("#track-map-message",false);runOnMainSync(()->h.web.invalidate());Thread.sleep(1500);h.screenshot("tracks-190-vector-map.png");check(true,"Offline vector max-zoom UI captured");
   h.js("document.querySelector('[data-page=chat]').click();document.querySelector('[data-action=chat-tools]').click();document.querySelector('[data-action=record-tools]').click()");until("!!document.querySelector('#open-source-notices')");h.js("document.querySelector('#open-source-notices').click()");until("document.querySelector('#editor').innerText.includes('GNU LESSER GENERAL PUBLIC LICENSE')");check(true,"Full bundled open-source licenses are readable without network");
   result.putString("stream","PASS "+passed+" vector/licensing UI checks\\n");finish(Activity.RESULT_OK,result);return;
  }
  if(phase.equals("seed")){
   check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.8.0"),"Seed original signed 1.8.0");
   JSONObject record=new JSONObject().put("id","offline-upgrade-190").put("type","learning").put("date",date).put("title","离线升级保留笔记").put("note","仅合成测试，保留学习原文").put("durationMinutes",17).put("platform","测试").put("contentType","article");h.call("saveRecord",new JSONObject().put("record",record).put("allowDuplicate",true));
   db.deleteDay(date);long base=TrackStore.dayStart(date);for(int i=0;i<8;i++)db.add(point(base+i*5000,i),"old-session");
   JSONObject snapshot=new JSONObject().put("init",h.call("init",new JSONObject())).put("raw",db.diagnostics(date).getJSONArray("rawPoints")).put("gpx",db.gpx(date));
   try(OutputStream o=getTargetContext().openFileOutput("offline-upgrade-190.json",0)){o.write(snapshot.toString().getBytes("UTF-8"));}
   check(true,"Learning, conversation, wiki, settings, GPS and GPX snapshot saved");
  }else{
   check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.9.0"),"Run signed 1.9.0 upgrade");
   ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=getTargetContext().openFileInput("offline-upgrade-190.json")){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);}JSONObject old=new JSONObject(bytes.toString("UTF-8")),now=(JSONObject)h.call("init",new JSONObject());
   for(String key:new String[]{"records","settings","messages","wikiPages"})if(old.getJSONObject("init").has(key)){
    if(key.equals("settings")){JSONObject a=old.getJSONObject("init").getJSONObject(key),b=now.getJSONObject(key);if(a.has("wikiAutomation"))a.getJSONObject("wikiAutomation").remove("dailyUsed");if(b.has("wikiAutomation"))b.getJSONObject("wikiAutomation").remove("dailyUsed");if(!a.toString().equals(b.toString())){java.util.List<String> diff=new ArrayList<>();java.util.Iterator<String> keys=a.keys();while(keys.hasNext()){String k=keys.next();if(!String.valueOf(a.opt(k)).equals(String.valueOf(b.opt(k))))diff.add(k);}throw new Exception("Persistent settings changed fields: "+diff);}}
    check(old.getJSONObject("init").get(key).toString().equals(now.get(key).toString()),"Upgrade preserves "+key);
   }
   // Idempotent cleanup of this test's own synthetic weak-fix fixture, never user data.
   db.getWritableDatabase().delete("points","session=?",new String[]{"poor"});
   check(old.getJSONArray("raw").toString().equals(db.diagnostics(date).getJSONArray("rawPoints").toString()),"Existing raw GPS bytes/telemetry preserved");check(old.getString("gpx").equals(db.gpx(date)),"Default D still yields exactly same GPX");
   TrackingService.prefs(getTargetContext()).edit().putString("mapMode","offline").putBoolean("mapConsent",false).commit();
   File fixture=new File(getTargetContext().getFilesDir(),"qa-vector.map");try(InputStream in=getContext().getAssets().open("mapsforge-with-data.map");OutputStream out=new FileOutputStream(fixture)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
   OfflineMap.importFile(getTargetContext(),Uri.fromFile(fixture));JSONObject info=OfflineMap.info(getTargetContext());check(info.getBoolean("configured")&&info.getString("kind").equals("mapsforge"),"Mapsforge .map validates and imports offline");
   MapFile mf=new MapFile(fixture);BoundingBox bounds=mf.boundingBox();double lat=(bounds.minLatitude+bounds.maxLatitude)/2,lon=(bounds.minLongitude+bounds.maxLongitude)/2;mf.close();
   int z=14,x=(int)((lon+180)/360*(1<<z)),y=(int)((1-Math.log(Math.tan(Math.toRadians(lat))+1/Math.cos(Math.toRadians(lat)))/Math.PI)/2*(1<<z));
   for(int zoom:new int[]{12,14,16,18}){int tx=(int)((lon+180)/360*(1<<zoom)),ty=(int)((1-Math.log(Math.tan(Math.toRadians(lat))+1/Math.cos(Math.toRadians(lat)))/Math.PI)/2*(1<<zoom));JSONObject tile=MapTiles.get(getTargetContext(),zoom,tx,ty,"",true);check(tile.getString("source").equals("mapsforge")&&tile.getInt("sourceZ")==zoom,"Real Mapsforge renders native zoom "+zoom+" without lower-resolution upscaling");}
   String before=OfflineMap.info(getTargetContext()).toString();File bad=new File(getTargetContext().getFilesDir(),"qa-bad.map");try(OutputStream out=new FileOutputStream(bad)){out.write("mapsforge binary OSMinvalid".getBytes("UTF-8"));}boolean rejected=false;try{OfflineMap.importFile(getTargetContext(),Uri.fromFile(bad));}catch(Exception e){rejected=true;}check(rejected&&before.equals(OfflineMap.info(getTargetContext()).toString()),"Invalid map import leaves previous map unchanged");
   JSONObject sampleTile=MapTiles.get(getTargetContext(),z,x,y,"",true);check(sampleTile.getString("source").equals("mapsforge"),"Previous map still renders after failed import");
   byte[] png=android.util.Base64.decode(sampleTile.getString("data").split(",")[1],android.util.Base64.DEFAULT);android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(png,0,png.length);java.util.Set<Integer> colors=new java.util.HashSet<>();for(int py=0;py<256;py+=2)for(int px=0;px<256;px+=2)colors.add(bitmap.getPixel(px,py));bitmap.recycle();check(colors.size()>2,"Rendered vector fixture contains actual styled map detail, not blank tile");
   long base=TrackStore.dayStart(date)+60000;Location poor=point(base,10);poor.setAccuracy(300);check(db.add(poor,"poor"),"300m raw uncertainty saved rather than discarded at ingestion");check(db.gpx(date,true).contains(Double.toString(poor.getLatitude())),"Raw GPX retains weak location");check(db.day(date).getJSONArray("points").length()==8,"D excludes poor raw fix without erasing it");
   db.deleteDay(full);base=TrackStore.dayStart(full);db.getWritableDatabase().beginTransaction();try{for(int i=0;i<43200;i++)db.add(point(base+i*2000,i),"full-day");db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}
   JSONObject day=db.day(full);check(!day.getBoolean("truncated")&&day.getInt("totalPoints")==43200&&day.getInt("processedPoints")==43200,"SQLite processes complete 24-hour 2-second day");JSONArray shown=day.getJSONArray("points");check(day.getBoolean("displaySimplified")&&shown.getJSONObject(shown.length()-1).getLong("time")==base+43199*2000,"Display reduction retains final daily location");
   String gpx=db.gpx(full);check(gpx.split("<trkpt ",-1).length-1==43200,"GPX exports all processed points, not simplified screen data");
   h.js("document.querySelector('[data-page=tracks]').click()");until("!!document.querySelector('#track-filter')");h.js("document.querySelector('#track-date').value='"+date+"';document.querySelector('#track-date').dispatchEvent(new Event('change'))");until("document.querySelector('#track-filter').value==='weighted65'");check(h.js("document.querySelector('#track-filter').options.length").equals("2"),"UI offers D default plus one explicitly experimental motion policy");
   h.js("document.querySelector('#track-filter').value='motion65';document.querySelector('#track-filter').dispatchEvent(new Event('change'))");until("document.querySelector('#track-bridge-legend').textContent.includes('运动辅助')");check(db.day(date).getJSONObject("filter").getString("id").equals("motion65"),"UI switch reaches native pipeline and GPX policy");
   check(db.diagnostics(date).getJSONArray("rawPoints").length()==9,"Policy switch keeps source points unchanged");h.js("document.querySelector('#track-filter').value='weighted65';document.querySelector('#track-filter').dispatchEvent(new Event('change'))");until("document.querySelector('#track-bridge-legend').textContent.includes('65米')");check(db.day(date).getJSONObject("filter").getString("id").equals("weighted65"),"Repeated switching returns to D");
   for(int i=0;i<3;i++){h.call("trackConfig",new JSONObject().put("mapMode","online").put("mapConsent",true));h.call("trackConfig",new JSONObject().put("mapMode","offline").put("mapConsent",false));check(MapTiles.get(getTargetContext(),z,x,y,"",true).getString("source").equals("mapsforge"),"Online/offline mode cycle "+(i+1)+" keeps local renderer usable");}
   getUiAutomation().grantRuntimePermission(getTargetContext().getPackageName(),android.Manifest.permission.ACCESS_FINE_LOCATION);getUiAutomation().grantRuntimePermission(getTargetContext().getPackageName(),android.Manifest.permission.ACCESS_COARSE_LOCATION);
   manager=(LocationManager)getTargetContext().getSystemService(Context.LOCATION_SERVICE);manager.addTestProvider("gps",false,false,false,false,true,true,true,Criteria.POWER_LOW,Criteria.ACCURACY_FINE);manager.setTestProviderEnabled("gps",true);
   h.call("trackStart",new JSONObject());for(int i=0;i<30&&!TrackingService.running;i++)Thread.sleep(100);check(TrackingService.running,"Foreground GPS and motion service starts");
   long t=System.currentTimeMillis();Location a=point(t,0);manager.setTestProviderLocation("gps",a);Thread.sleep(2400);Location b=point(t+2400,1);b.setAccuracy(300);manager.setTestProviderLocation("gps",b);Thread.sleep(2400);Location c=point(t+4800,100000);manager.setTestProviderLocation("gps",c);Thread.sleep(700);
   String today=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());JSONArray raw=db.diagnostics(today).getJSONArray("rawPoints");boolean foundA=false,foundB=false,foundC=false;for(int i=0;i<raw.length();i++){JSONObject r=raw.getJSONObject(i);if(r.getLong("time")==t)foundA=true;if(r.getLong("time")==t+2400)foundB=r.getDouble("accuracy")==300;if(r.getLong("time")==t+4800)foundC=r.getJSONObject("telemetry").optString("capturePolicy").equals("raw-v2");}
   check(foundA&&foundB&&foundC,"Real LocationManager retains sub-4s, weak and jump callbacks in raw database");
   h.call("trackStop",new JSONObject());Thread.sleep(500);check(!TrackingService.running,"Pause removes location and sensor listeners");
   String visual="2026-11-05";db.deleteDay(visual);long visualBase=TrackStore.dayStart(visual)+36000000;for(int i=0;i<10;i++){Location v=point(visualBase+i*5000,i);v.setLatitude(lat+i*.00001);v.setLongitude(lon);db.add(v,"vector-visual");}
   h.js("document.querySelector('#track-date').value='"+visual+"';document.querySelector('#track-date').dispatchEvent(new Event('change'))");until("document.querySelector('#track-map-message').textContent.includes('离线 OSM 底图')");check(true,"WebView paints real native vector tiles offline");
   h.tap(".page-title",false);runOnMainSync(()->h.web.invalidate());Thread.sleep(1500);h.screenshot("tracks-190-offline.png");
  }
  result.putString("stream","PASS "+passed+" offline/upgrade checks ("+phase+")\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){e.printStackTrace();result.putString("stream","FAIL after "+passed+": "+e+"\n");finish(Activity.RESULT_CANCELED,result);}finally{getTargetContext().stopService(new Intent(getTargetContext(),TrackingService.class));if(manager!=null)try{manager.removeTestProvider("gps");}catch(Exception ignored){}}}
}
